def row(venue, pe, tool, rule, appeal, applies, eff, url, quote, notes, vq, vn):
    return dict(venue=venue, policy_exists=pe, tool_named=tool, threshold_or_rule=rule, appeal_process=appeal,
                applies_to=applies, effective_date=eff, source_url=url, access_date=D, quote=quote,
                source_type='official', notes=notes, verify_status='confirmed', verify_url=url,
                verify_date=D, verify_quote=vq, verify_note=vn)

